import re, csv

ttl = open(GRAPH_TTL).read()

# Find all sensor blocks of type Zone_Air_Temperature_Sensor
# Pattern: <subject> a brick:Zone_Air_Temperature_Sensor ; <block>  .
pattern = re.compile(
    r'(\S+)\s+a\s+brick:Zone_Air_Temperature_Sensor\s+;(.*?)\.',
    re.DOTALL
)
sensors = []
for m in pattern.finditer(ttl):
    subj = m.group(1)
    block = m.group(2)
    ipt = re.search(r'brick:isPointOf\s+(\S+)\s*;', block)
    ref = re.search(r'ref:hasExternalReference\s*<([^>]+)>', block)
    sensors.append({
        'sensor': subj,
        'zone': ipt.group(1) if ipt else None,
        'ref': ref.group(1) if ref else None,
    })
print('sensors:', len(sensors))

# zone names
zone_names = {}
for zpat in re.finditer(r'(\S+)\s+a\s+brick:HVAC_Zone\s+(.*?)(?=^bldg:|\Z)', ttl, re.DOTALL|re.MULTILINE):
    z = zpat.group(1)
    nm = re.search(r'brick:hasName\s+([\w\-]+)', zpat.group(2))
    if nm:
        zone_names[z] = nm.group(1)
print('zones:', len(zone_names), list(zone_names.items())[:5])

# catalog: map timeseries_id -> point_uri perhaps
catalog = {}
with open(CATALOG_CSV) as f:
    for r in csv.DictReader(f):
        catalog[r['timeseries_id']] = r

# build zone -> tsid mapping
zone_to_ts={}
for s in sensors:
    zone = s['zone']
    refid = s['ref'].split(':')[-1] if s['ref'] else None
    zone_to_ts[zone] = refid

# Filter to those that exist in catalog
present = [(z, t, zone_names.get(z)) for z, t in zone_to_ts.items() if t and t in catalog]
print('present:', len(present))
# pick values for 2018-04-25 15:00
target = '2018-04-25T15:00'
# load values
vals = {}
with open(VALUES_CSV) as f:
    for r in csv.DictReader(f):
        ts = r['timeseries_id']
        if ts not in vals:
            vals[ts] = {}
        vals[ts][r['timestamp']] = r['value']

best=None
for z, t, name in present:
    d = vals.get(t, {})
    if target in d:
        v = float(d[target])
        if best is None or v > best[1]:
            best = (name, v, z)
    else:
        # check any key around target
        pass
print('best:', best)

